```javascript
var abbreviateProduct = function(left, right) {
    // Exact tracking while small
    let exact = 1n;
    let exactOk = true;
    let zeros = 0;
    const LIM = 1000000000000000n;
    let t2 = 0, t5 = 0;
    let mod = 1;
    let logSum = 0;
    for (let i = left; i <= right; i++) {
        let x = i;
        while (x % 2 === 0) { x /= 2; t2++; }
        while (x % 5 === 0) { x /= 5; t5++; }
        mod = (mod * (x % 100000)) % 100000;
        logSum += Math.log10(i);
        if (exactOk) {
            exact *= BigInt(i);
            while (exact % 10n === 0n) { exact /= 10n; zeros++; }
            if (exact > LIM) exactOk = false;
        }
    }
    const C = Math.min(t2, t5);
    if (exactOk) {
        const s = exact.toString();
        if (s.length <= 10) return s + "e" + zeros;
        return s.slice(0, 5) + "..." + s.slice(-5) + "e" + zeros;
    }
    // suffix
    if (t2 > C) {
        for (let k = 0; k < t2 - C; k++) mod = (mod * 2) % 100000;
    } else if (t5 > C) {
        for (let k = 0; k < t5 - C; k++) mod = (mod * 5) % 100000;
    }
    let suf = String(mod).padStart(5, "0");
    let s = logSum - C;
    let frac = s - Math.floor(s);
    let pre = Math.floor(Math.pow(10, frac + 4) + 1e-9);
    return String(pre) + "..." + suf + "e" + C;
};
```

