    const N = this.N;
    let pos = 0, c = 0, s = 0;
    for (let step = 65536; step >= 1; step >>= 1) {
        const np = pos + step;
        if (np <= N && c + this.cnt[np] <= n) {
            pos = np;
            c += this.cnt[np];
            s += this.sm[np];
        }
    }
    if (c < n) {
        s += (n - c) * (pos + 1);
    }
    return s;
};

