```javascript
/**
 * @param {number[][]} points
 * @return {number}
 */
var maxPoints = function(points) {
    const n = points.length;
    if (n <= 2) return n;
    const gcd = (a, b) => {
        while (b) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    let best = 1;
    for (let i = 0; i < n; i++) {
        const map = new Map();
