This is a bitmask DP over which elements have been used. The starter is a function expression, so I keep that shape.

Let `dp[mask]` be the maximum score obtainable once the elements in `mask` have been removed. The operation number is `popcount(mask)/2 + 1`. For each mask with an even popcount, I pick the first unused index `i` and pair it with each later unused index `j`, which avoids counting the same pairing in different orders. The new score is `dp[mask] + op * gcd[i][j]`, stored into `dp[mask | (1<<i) | (1<<j)]`.

Setup details:
- With `m = 2n ≤ 14`, there are 16384 masks and about 100 transitions per mask, so this is fast.
- I precompute the pairwise gcds.
- `dp` is initialized to -1 for unreachable masks, with `dp[0] = 0`.
- The answer is `dp[(1<<m) - 1]`.

```javascript
/**
 * @param {number[]} nums
 * @return {number}
 */
var maxScore = function(nums) {
    const m = nums.length;
    const gcd = (a, b) => {
        while (b) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    const g = [];
    for (let i = 0; i < m; i++) {
        g.push(new Array(m).fill(0));
        for (let j = 0; j < m; j++) {
            g[i][j] = gcd(nums[i], nums[j]);
        }
    }
    const size = 1 << m;
    const dp = new Array(size).fill(-1);
    dp[0] = 0;
    const pc = (x) => {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    };
    for (let mask = 0; mask < size; mask++) {
        if (dp[mask] < 0) continue;
        const cnt = pc(mask);
        if (cnt % 2 !== 0) continue;
        const op = cnt / 2 + 1;
        let i = 0;
        while (i < m && (mask & (1 << i))) i++;
        if (i >= m) continue;
        for (let j = i + 1; j < m; j++) {
            if (mask & (1 << j)) continue;
            const nm = mask | (1 << i) | (1 << j);
            const v = dp[mask] + op * g[i][j];
            if (v > dp[nm]) dp[nm] = v;
        }
    }
    return dp[size - 1];
};
```

