var maxRunTime = function(n, batteries) {
    batteries.sort((a, b) => b - a);
    let sum = 0;
    for (const b of batteries) sum += b;
    let i = 0;
    while (n > 1 && batteries[i] * n > sum) {
        sum -= batteries[i];
        n--;
        i++;
    }
    return Math.floor(sum / n);
};
```

