This is a bitmask DP over rows. For each row, the state is the set of columns where students sit.

A mask is valid for a row if:
- every chosen seat is a good seat (not `'#'`),
- no two chosen seats are adjacent, i.e. `mask & (mask >> 1) == 0`.

Two consecutive rows are compatible if no student in the current row has a student in the previous row at the upper left or upper right: `(mask & (prev << 1)) == 0` and `(mask & (prev >> 1)) == 0`.

The recurrence is `dp[i][mask] = popcount(mask) + max over compatible prev of dp[i-1][prev]`. The answer is the maximum over the last row's states.

The examples show seat strings with trailing spaces (like `"# "`), which look like formatting artifacts. To be safe, I treat a seat as broken only if its first character is `'#'`, and as good otherwise. In Example 3 the `**.**` entries are also artifacts, and under this rule they count as good seats, since they don't start with `#`.

Implementation details:
- For each row, compute `good` as a bitmask where bit j is set if the seat is not `'#'`.
- Initialize `dp` as an array of size `2^n` filled with -1 (unreachable), with `dp[0] = 0` as the virtual row before row 0.
- For each row, build `ndp`. For each valid mask (`mask & ~good == 0` and no adjacent bits), try every `prev` with `dp[prev] >= 0` that is compatible, and set `ndp[mask] = max(dp[prev] + popcount(mask))`.
- The result is the maximum of the final `dp`.

```javascript
/**
 * @param {character[][]} seats
 * @return {number}
 */
var maxStudents = function(seats) {
    const m = seats.length;
    const n = seats[0].length;
    const size = 1 << n;
    const pc = (x) => {
        let c = 0;
        while (x) { c += x & 1; x >>= 1; }
        return c;
    };
    let dp = new Array(size).fill(-1);
    dp[0] = 0;
    for (let i = 0; i < m; i++) {
        let good = 0;
        for (let j = 0; j < n; j++) {
            const ch = String(seats[i][j])[0];
            if (ch !== '#') good |= (1 << j);
        }
        const ndp = new Array(size).fill(-1);
        for (let mask = 0; mask < size; mask++) {
            if ((mask & ~good) !== 0) continue;
            if ((mask & (mask >> 1)) !== 0) continue;
            const cnt = pc(mask);
            for (let prev = 0; prev < size; prev++) {
                if (dp[prev] < 0) continue;
                if ((mask & (prev << 1)) !== 0) continue;
                if ((mask & (prev >> 1)) !== 0) continue;
                const v = dp[prev] + cnt;
                if (v > ndp[mask]) ndp[mask] = v;
            }
        }
        dp = ndp;
    }
    return Math.max(...dp);
};
