    const n = flowers.length;
    const a = flowers.map(x => Math.min(x, target));
    a.sort((x, y) => x - y);
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
    let best = 0;
    for (let i = n; i >= 0; i--) {
        const cost = (n - i) * target - (pre[n] - pre[i]);
        if (cost > newFlowers) break;
        const rem = newFlowers - cost;
        if (i === 0) {
            best = Math.max(best, n * full);
            continue;
        }
        // largest p in [1..i] with a[p-1]*p - pre[p] <= rem
        let lo = 1, hi = i;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            if (a[mid - 1] * mid - pre[mid] <= rem) lo = mid;
            else hi = mid - 1;
        }
        const p = lo;
        const m = Math.min(target - 1, Math.floor((rem + pre[p]) / p));
        best = Math.max(best, (n - i) * full + m * partial);
    }
    return best;
};
```

