/**
 * @param {number[][]} grid
 * @return {number}
 */
var minDays = function(grid) {
    const m = grid.length, n = grid[0].length;
    function count() {
        const vis = new Uint8Array(m * n);
        let c = 0;
        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (grid[i][j] === 1 && !vis[i * n + j]) {
                    c++;
                    const st = [i * n + j];
                    vis[i * n + j] = 1;
                    while (st.length) {
                        const cur = st.pop();
                        const x = (cur / n) | 0, y = cur % n;
