Approach: union-find. For each request, find the roots of u and v. If they are already the same, the request succeeds. Otherwise, check every restriction: if its endpoints' roots are {ru, rv} in either order, the request fails. If no restriction blocks it, union the two sets and mark the request as successful.

The cost is O(requests × restrictions × α), about 10^6 operations, which is fine.

```javascript
var friendRequests = function(n, restrictions, requests) {
    const parent = Array.from({length: n}, (_, i) => i);
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const res = [];
    for (const [u, v] of requests) {
        const ru = find(u), rv = find(v);
        if (ru === rv) {
            res.push(true);
            continue;
        }
        let ok = true;
        for (const [x, y] of restrictions) {
            const rx = find(x), ry = find(y);
            if ((rx === ru && ry === rv) || (rx === rv && ry === ru)) {
                ok = false;
                break;
            }
        }
        if (ok) parent[ru] = rv;
        res.push(ok);
    }
    return res;
};
```

