Minimizing (sessions, time) lexicographically is a valid greedy for this DP: fewer sessions is always at least as good as more, and with equal sessions less time in the last one is better.

I store the pair as one number, `sessions * 100 + time`, so a plain numeric comparison gives the lexicographic order. With n ≤ 14 and times ≤ 15 this is tiny.

```javascript
/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const full = (1 << n) - 1;
    const INF = 1e9;
    const dp = new Array(full + 1).fill(INF);
    dp[0] = 100; // sessions=1, time=0
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] >= INF) continue;
        const s = Math.floor(dp[mask] / 100);
        const t = dp[mask] % 100;
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            let ns, nt;
            if (t + tasks[i] <= sessionTime) {
                ns = s;
                nt = t + tasks[i];
            } else {
                ns = s + 1;
                nt = tasks[i];
            }
            const v = ns * 100 + nt;
            const nm = mask | (1 << i);
            if (v < dp[nm]) dp[nm] = v;
        }
    }
    return Math.floor(dp[full] / 100);
};
