```javascript
/**
 * @param {number[]} arr
 * @return {number}
 */
var sumOddLengthSubarrays = function(arr) {
    const n = arr.length;
    let total = 0;
    for (let i = 0; i < n; i++) {
        const L = i + 1, R = n - i;
        const oL = Math.floor((L + 1) / 2), eL = Math.floor(L / 2);
        const oR = Math.floor((R + 1) / 2), eR = Math.floor(R / 2);
        total += arr[i] * (oL * oR + eL * eR);
