var suggestedProducts = function(products, searchWord) {
    products.sort();
    let lo = 0, hi = products.length - 1;
    const res = [];
    for (let i = 0; i < searchWord.length; i++) {
        const c = searchWord[i];
        while (lo <= hi && products[lo][i] !== c) lo++;
        while (lo <= hi && products[hi][i] !== c) hi--;
        const cur = [];
        for (let k = lo; k <= hi && k < lo + 3; k++) cur.push(products[k]);
        res.push(cur);
    }
    return res;
